    by_topic: (m.clusters.clusters || []).slice(0, 6).map(s => s.key + ': named ' + s.mention_rate + '%' + (s.volume ? ', ' + s.volume + ' AI searches/mo' : '') + (s.leader ? ', leader ' + s.leader : '')),
