    crawler_access: A ? { ok: A.ok, answer_bots_allowed: A.answer_bots_ok + ' of ' + A.answer_bots, training_bots_blocked: A.training_blocked, llms_txt: A.llms_txt.found, issues: A.issues.map(x => x.level + ': ' + x.text) } : 'not checked',
    market_wide_index: X ? { platforms: X.platforms, your_share_pct: X.sov, answers_citing_you: X.answers_citing_you, brands: (X.brands || []).slice(0, 6).map(b => (b.domain || b.name) + ' ' + b.mentions + ' mentions' + (b.share != null ? ' (' + b.share + '%)' : '')), carried: !!X.carried } : null,
    demand: { ai_searches_behind_panel: M.demand_total, estimated_answers_naming_you: M.ai_impressions, in_questions_you_lose: M.lost_demand },
    market_view: m.market ? { topic: m.market.keyword, top_domains: (m.market.top || []).slice(0, 8).map(x => x.domain + ' ' + x.mentions), your_position: m.market.you || 'not in the list' } : null, alerts: m.alerts.map(a => a.text), computed_actions: m.actions.map(a => a.action + ' — ' + a.why) };
